public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return; // nothing to schedule
    }
    // Collect all files and directories in a stack (DFS)
    java.util.LinkedList<File> stack = new java.util.LinkedList<>();
    java.util.ArrayList<File> toDelete = new java.util.ArrayList<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        toDelete.add(current);
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
    }
    // Schedule deletion in reverse order (children before parents)
    for (int i = toDelete.size() - 1; i >= 0; i--) {
        toDelete.get(i).deleteOnExit();
    }

