public void abbreviate(final int nameStart,final StringBuffer buf) {
    if (name == null || nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    // Simple abbreviation: keep the first character after each delimiter
    // (e.g., '_' or '-') and copy the delimiter itself to the buffer.
    char prev = 0;
    for (int i = nameStart; i < name.length(); i++) {
        char c = name.charAt(i);
        if (c == '_' || c == '-') {
            buf.append(c);
            prev = c;
        } else {
            if (i == nameStart || prev == '_' || prev == '-') {
                buf.append(c);
            }
            prev = c;
        }
    }
}

