public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (len <= 0 || str == null) {
        return 0;
    }
    int end = index + len;
    int utf8Size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) {
            // ASCII
            utf8Size += 1;
        } else if (ch <= 0x07FF) {
            // 2-byte sequence
            utf8Size += 2;
        } else {
            // Check for surrogate pairs
            if (Character.isHighSurrogate(ch) && i + 1 < end) {
                char lo = str.charAt(i + 1);
                if (Character.isLowSurrogate(lo)) {
                    // Surrogate pair => U+10000 .. U+10FFFF => 4-byte sequence
                    utf8Size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            // BMP non-ASCII => 3-byte sequence
            utf8Size += 3;
        }
    }
    return utf8Size;
}

