public final byte[] toByteArray() {
    // Calculate total size of all buffers that contain data
    int totalSize = 0;
    for (ByteBuffer buf : buffers) {
        totalSize += buf.remaining();
    }

    // Allocate byte array to hold combined data
    byte[] result = new byte[totalSize];
    int position = 0;

    // Copy data from each buffer into the result array
    for (ByteBuffer buf : buffers) {
        int len = buf.remaining();
        // If buffer has backing array, copy directly
        if (buf.hasArray()) {
            System.arraycopy(buf.array(), buf.arrayOffset() + buf.position(), result, position, len);
        } else {
            // Fallback: copy byte by byte
            for (int i = 0; i < len; i++) {
                result[position + i] = buf.get();
            }
        }
        position += len;
    }

    return result;
}

